<template>
  <div class="container mt-3" v-if="route.params.module === 'all'">
    <Mjuni/>
  </div>

  <div class="layout-px-spacing">

    <!-- Show multiselect only when 'all' -->
    <div v-if="isAll" class="d-flex ms-auto w-25">
      <Multiselect
        v-model="form"
        :options="forms"
        label="name"
        placeholder="Select form"
        :searchable="true"
      />
    </div>

    <template v-if="form">
      <hr>
      <DynamicFormAndTable :key="form.name ?? form + '_table'" :form="form.name ?? form" ref="tableRef" />
    </template>
   <template v-else>
  <div class="container d-flex justify-content-center align-items-center" style="min-height: 60vh;">
    <div class="card text-center p-5 border border-warning shadow-sm" style="max-width: 500px;">
      
      <div class="mb-4">
        <svg width="80" height="80" viewBox="0 0 24 24" fill="none">
          <path d="M12 2L2 20h20L12 2z" stroke="#ffc107" stroke-width="2" fill="#fff3cd"/>
          <path d="M12 8v5" stroke="#ffc107" stroke-width="2" stroke-linecap="round"/>
          <circle cx="12" cy="16" r="1.2" fill="#ffc107"/>
        </svg>
      </div>

      <h3 class="fw-bold text-dark mb-2">No Module Selected</h3>
      <p class="text-muted mb-0">Please select a module to continue</p>

    </div>
  </div>
</template>

  </div>
</template>

<script setup>
import { ref, onMounted, watch, nextTick, computed } from 'vue'
import { useRoute } from 'vue-router'
import axios from 'axios'
import DynamicFormAndTable from '@/components/dynamicSchema/dynamicFormAndTable.vue'
import Multiselect from '@suadelabs/vue3-multiselect'
import '@suadelabs/vue3-multiselect/dist/vue3-multiselect.css'
import Mjuni from '@/components/dynamicSchema/navbar.vue'

const route    = useRoute()
const api      = axios.create({ baseURL: 'https://bushman.ink/api/v2/' })
const tableRef = ref(null)
const forms    = ref([])
const form     = ref(null)

const isAll = computed(() => route.params.module === 'all')

const getForms = async () => {
  const response = await api.get('form-lists')
  forms.value = response.data

  if (!isAll.value) {
    // Find and set the specific form directly
    form.value = forms.value.find(f => f.name === route.params.module) ?? null
  }
}

watch(() => route.params.module, async (newVal) => {
    if (newVal === 'all') {
        await getForms()
        form.value = null
    } else {
        form.value = newVal
    }
}, { immediate: true })

</script>